WITH exploded AS (SELECT id, host, log_ts, level, latency_ms, status_code, attr_key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS attr_key, v) SELECT host, log_ts, latency_ms, status_code, attr_key, v, CASE WHEN attr_key RLIKE '^(trace|region)$' THEN 'EXTENDED' WHEN attr_key RLIKE '^(version)$' THEN 'GROUP_B' ELSE 'GROUP_A' END AS attr_key_zone FROM exploded ORDER BY attr_key DESC NULLS LAST;
